 "content": "def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2]
    if not points:
        return out
    rows = sorted(r for r, c in points)
    cols = sorted(c for r, c in points)
    mid = len(points) // 2
    spine_row = rows[mid]
    spine_col = cols[mid]
    horizontal_cost = max(cols) - min(cols) + sum(abs(r - spine_row) for r, c in points)
    vertical_cost = max(rows) - min(rows) + sum(abs(c - spine_col) for r, c in points)
    if horizontal_cost <= vertical_cost:
        for c in range(min(cols), max(cols) + 1):
            if out[spine_row][c] == 0:
                out[spine_row][c] = 3
        for r, c in points:
            for rr in range(min(r, spine_row), max(r, spine_row) + 1):
                if out[rr][c] == 0:
                    out[rr][c] = 3
    else:
        for r in range(min(rows), max(rows) + 1):
            if out[r][spine_col] == 0:
                out[r][spine_col] = 3
        for r, c in points:
            for cc in range(min(c, spine_col), max(c, spine_col) + 1):
                if out[r][cc] == 0:
                    out[r][cc] = 3
    return out
